import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // Aspect ratio from atlas region
  const regW = 512;
  const regH = 320;
  const aspect = regW / regH;

  // Geometry sized to unit height, width = aspect
  const geometry = new PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  const mesh = new Mesh(geometry, material);
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.lookAt(camera.position);
  };

  group.add(mesh);

  // Load texture and apply atlas UV offset
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((texture) => {
    // Determine image dimensions from texture source
    const img = texture.image;
    const imgW = img ? img.width : 1;
    const imgH = img ? img.height : 1;

    // Calculate UV repeat and offset to select the source rect
    // Source rect is top-left origin (0,0) in pixel coords
    // Three.js texture UV origin is bottom-left (0,0)
    // So offset.y = (imgH - regH) / imgH to shift to top-left
    const repeatX = regW / imgW;
    const repeatY = regH / imgH;
    const offsetX = 0;
    const offsetY = (imgH - regH) / imgH;

    texture.repeat.set(repeatX, repeatY);
    texture.offset.set(offsetX, offsetY);
    texture.needsUpdate = true;

    material.map = texture;
    material.needsUpdate = true;
  }).catch((err) => {
    console.warn('Texture load failed:', err);
  });

  // Apply position/rotation/scale from config
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  } else if (config.position) {
    group.position.copy(config.position);
  }
  if (config.rotation) {
    group.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  }
  if (config.scale) {
    group.scale.set(config.scale.x, config.scale.y, config.scale.z);
  }

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // Dispose texture if loaded
    if (material.map) {
      material.map.dispose();
    }
  };

  // Event handlers (none required, but maintain structure)
  group.userData.handlers = {};

  return group;
}
